using System.Text.Json.Serialization;

namespace Intropy.Topology.Models;

/// <summary>
/// Infrastructure the components depend on. The <see cref="Type"/> decides which
/// optional fields apply; for <see cref="ResourceType.Topic"/> those are
/// <see cref="PubSub"/> and <see cref="Entity"/>.
/// </summary>
public sealed class Resource
{
    /// <summary>The resource's unique name within the system.</summary>
    public required string Name { get; set; }

    /// <summary>The resource kind.</summary>
    public required ResourceType Type { get; set; }

    /// <summary>Topic field: the pub/sub broker name carrying the topic.</summary>
    [JsonPropertyName("pubsub")]
    public string? PubSub { get; set; }

    /// <summary>Topic field: the data entity on the topic, e.g. "RawProduct".</summary>
    public string? Entity { get; set; }

    /// <summary>
    /// Creates a topic resource. Convenient for declaring reusable topic
    /// references (e.g. in a static holder) that components then publish to or
    /// consume from.
    /// </summary>
    public static Resource Topic(string name, string? entity = null, string? pubsub = null) =>
        new() { Name = name, Type = ResourceType.Topic, Entity = entity, PubSub = pubsub };
}
