namespace Intropy.Topology.Models;

/// <summary>
/// Records what produced a topology record, so a stale file can be traced back
/// to the tool and commit that generated it.
/// </summary>
public sealed class Generator
{
    /// <summary>The generating tool's name.</summary>
    public string Tool { get; set; } = "Intropy.Topology";

    /// <summary>The generator version, e.g. "0.1.0".</summary>
    public string? Version { get; set; }

    /// <summary>Provenance of the input, e.g. "orders@local" or "integrations@3f9c2e1".</summary>
