    public void Full_build_serializes_to_the_expected_record()
    {
        var system = SystemBuilder.Create("product-distribution")
            .WithOwner("group:default/team-integration")
            .InDomain("distribution")
            .GeneratedBy("Intropy.Topology", version: "0.1.0", source: "integrations@3f9c2e1");

        var productRaw = system.AddTopic(
            "product-raw", entity: "RawProduct", pubsub: "product-distribution-pubsub");

        system.AddExtractor("pim-extractor")
            .WithTags("int-042")
            .InProject("pim-extractor")
            .Workload("cronjob")
            .OnSchedule("*/15 * * * *")
            .Publishes(productRaw);

        system.AddLoader("erp-loader")
            .InProject("erp-loader")
            .Consumes(productRaw);

        Assert.True(
            JsonNode.DeepEquals(JsonNode.Parse(system.ToJson()), JsonNode.Parse(Expected)),
            $"Serialized topology did not match the expected record.\nActual:\n{system.ToJson()}");
    }
}

