using Intropy.Topology.Models;

namespace Intropy.Topology.Building;

/// <summary>
/// The entry point for authoring a system topology. Wraps a
/// <see cref="SystemTopology"/> model and exposes fluent helpers for declaring
/// topics and blocks; the block helpers return a <see cref="ComponentBuilder"/>
/// for wiring relationships.
/// </summary>
public sealed class SystemBuilder
{
    private readonly SystemTopology _topology;

    private SystemBuilder(SystemTopology topology) => _topology = topology;

    /// <summary>Starts a new topology for the named system.</summary>
    public static SystemBuilder Create(string systemName) => new(new SystemTopology(systemName));

    /// <summary>The underlying topology model being built.</summary>
    public SystemTopology Topology => _topology;

    /// <summary>Sets the owning team, as a Backstage Group ref.</summary>
    public SystemBuilder WithOwner(string owner)
    {
        _topology.Owner = owner;
        return this;
    }

    /// <summary>Sets the system's business domain.</summary>
    public SystemBuilder InDomain(string domain)
    {
        _topology.Domain = domain;
        return this;
    }

    /// <summary>Sets the generator provenance recorded in the file.</summary>
    public SystemBuilder GeneratedBy(string tool, string? version = null, string? source = null)
    {
        _topology.Generator = new Generator { Tool = tool, Version = version, Source = source };
        return this;
    }

    /// <summary>Declares a topic resource and returns it so components can reference it.</summary>
    public Resource AddTopic(string name, string? entity = null, string? pubsub = null)
    {
        var topic = Resource.Topic(name, entity, pubsub);
        _topology.Resources.Add(topic);
        return topic;
    }

    /// <summary>Adds an extractor block.</summary>
    public ComponentBuilder AddExtractor(string name) => AddComponent(name, ComponentType.Extractor);

    /// <summary>Adds a loader block.</summary>
    public ComponentBuilder AddLoader(string name) => AddComponent(name, ComponentType.Loader);

    /// <summary>Adds a transactional integration block.</summary>
    public ComponentBuilder AddTransactionalIntegration(string name) =>
        AddComponent(name, ComponentType.TransactionalIntegration);

    /// <summary>Adds a component of any type and returns a builder for wiring it.</summary>
    public ComponentBuilder AddComponent(string name, ComponentType type)
    {
        var component = new Component { Name = name, Type = type };
        _topology.Components.Add(component);
        return new ComponentBuilder(_topology, component);
    }

    /// <summary>Returns the finished topology model.</summary>
    public SystemTopology Build() => _topology;

    /// <summary>Serializes the topology to its <c>topology.json</c> representation.</summary>
    public string ToJson() => _topology.ToJson();

    /// <summary>Serializes the topology and writes it to <paramref name="path"/>.</summary>
    public void Save(string path) => _topology.Save(path);
}

